-- =============================================================================
-- Opciones sandbox: «Restablecer piloto». Deja la base como recién instalada: sin actas ni causas, con los usuarios de
-- prueba y la configuración de origen (plantillas de escritos con su versión 1, ordenanzas, valores y tarifas,
-- feriados, textos del portal, catálogos, marcas y modelos y permisos por defecto).
-- El estado de origen se guarda en sandbox_snapshot con nombre 'origen' (al final de este archivo); se generó con
-- init.sql y las migraciones 002 a 028 en una base vacía. Correr después de 028. Se puede correr más de una vez.
-- Si una migración nueva agrega datos de configuración, hay que regenerar el origen: en una base nueva con todas las
-- migraciones, SELECT sandbox_capturar_origen(); y copiar el snapshot (o correr la migración nueva después de restablecer).
-- =============================================================================

-- Tablas de configuración que vuelven al origen (padres primero). Los usuarios los restablece sandbox_resetear_usuarios().
CREATE OR REPLACE FUNCTION sandbox_tablas_config() RETURNS TEXT[] LANGUAGE sql STABLE AS $$
  SELECT coalesce(array_agg(t ORDER BY o), ARRAY[]::TEXT[])
  FROM unnest(ARRAY['catalogo','configuracion','feriado','ley','permiso_rol','texto_portal','plantilla','plantilla_version',
                    'vehiculo_marca','vehiculo_modelo'])
       WITH ORDINALITY AS x(t, o)
  WHERE to_regclass('public.' || t) IS NOT NULL;
$$;

-- Guarda la configuración actual como estado de origen (para regenerarlo en una base recién instalada).
CREATE OR REPLACE FUNCTION sandbox_capturar_origen() RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE t TEXT; arr JSONB; datos JSONB := '{}'; res JSONB := '{}';
BEGIN
  FOREACH t IN ARRAY sandbox_tablas_config() LOOP
    EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY (to_jsonb(x) ->> ''id'')::bigint NULLS LAST, to_jsonb(x)::text), ''[]'') FROM %I x', t) INTO arr;
    datos := datos || jsonb_build_object(t, arr);
    res := res || jsonb_build_object(t, jsonb_array_length(arr));
  END LOOP;
  INSERT INTO sandbox_snapshot (nombre, datos, creado_at, creado_por)
  VALUES ('origen', datos, (extract(epoch from now()) * 1000)::bigint, 'Instalación')
  ON CONFLICT (nombre) DO UPDATE SET datos = EXCLUDED.datos, creado_at = EXCLUDED.creado_at, creado_por = EXCLUDED.creado_por;
  RETURN res;
END $$;

-- Restablecer piloto: borra todos los datos, vuelve la configuración al origen y deja solo los usuarios de prueba.
-- Una sola transacción: si algo falla, no cambia nada.
CREATE OR REPLACE FUNCTION sandbox_restablecer() RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE s RECORD; t TEXT; arr JSONB; cols TEXT; maxid BIGINT; res JSONB := '{}';
BEGIN
  SELECT * INTO s FROM sandbox_snapshot WHERE nombre = 'origen';
  IF NOT FOUND THEN RAISE EXCEPTION 'Falta el estado de origen: corra sql/029_sandbox_restablecer.sql'; END IF;
  res := jsonb_build_object('datos_borrados', (SELECT coalesce(sum(value::bigint), 0) FROM jsonb_each_text(sandbox_borrar())));
  EXECUTE 'TRUNCATE ' || array_to_string(sandbox_tablas_config(), ', ') || ' RESTART IDENTITY CASCADE';
  FOREACH t IN ARRAY sandbox_tablas_config() LOOP
    arr := coalesce(s.datos -> t, '[]');
    IF jsonb_array_length(arr) > 0 THEN
      -- Solo las columnas que trae el origen: las agregadas después toman su valor por defecto.
      SELECT string_agg(quote_ident(c.column_name), ', ' ORDER BY c.ordinal_position) INTO cols
      FROM information_schema.columns c
      WHERE c.table_schema = 'public' AND c.table_name = t AND (arr -> 0) ? c.column_name;
      EXECUTE format('INSERT INTO %I (%s) SELECT %s FROM jsonb_populate_recordset(NULL::%I, $1)', t, cols, cols, t) USING arr;
      IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = t AND column_name = 'id')
         AND pg_get_serial_sequence(t, 'id') IS NOT NULL THEN
        EXECUTE format('SELECT max(id) FROM %I', t) INTO maxid;
        PERFORM setval(pg_get_serial_sequence(t, 'id'), greatest(maxid, 1));
      END IF;
    END IF;
    res := res || jsonb_build_object(t, jsonb_array_length(arr));
  END LOOP;
  res := res || jsonb_build_object('usuario', sandbox_resetear_usuarios() -> 'creados');
  RETURN res;
END $$;

-- Solo las puede llamar el servidor (service_role).
REVOKE EXECUTE ON FUNCTION sandbox_restablecer(), sandbox_capturar_origen() FROM PUBLIC;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') AND EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
    REVOKE EXECUTE ON FUNCTION sandbox_restablecer(), sandbox_capturar_origen() FROM anon, authenticated;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
    GRANT EXECUTE ON FUNCTION sandbox_restablecer(), sandbox_capturar_origen() TO service_role;
  END IF;
END $$;

